21	  ApiClient({
22	    required this._dio,
23	    required this._tokenStorage,
24	    required this._anonKey,
25	  });
26	
27	  final Dio _dio;
28	  final SecureTokenStorage _tokenStorage;
29	  final String _anonKey;
