31	  Future<Either<Failure, Map<String, dynamic>>> call(
32	    String function, {
33	    required String method,
34	    Map<String, dynamic>? body,
35	    List<String>? pathSegments,
36	    Map<String, dynamic>? queryParameters,
37	    AuthMode authMode = AuthMode.userSession,
38	    // When false, returns the full decoded body (`{"data": ..., "meta":
39	    // ...}`) verbatim instead of unwrapping/validating the inner "data"
40	    // object. Needed by `entries-list`, whose "data" is an array (not an
41	    // object) and whose "meta.nextCursor" every other call site has no use
42	    // for and would otherwise be discarded. Every pre-existing call site
43	    // omits this and is byte-for-byte unaffected.
44	    bool unwrapData = true,
45	  }) async {
46	    final baseUrl = dotenv.env['FUNCTIONS_BASE_URL'] ?? '';
47	    final segments = [function, ...?pathSegments];
48	    final url = '$baseUrl/${segments.join('/')}';
49	
50	    final bearer = authMode == AuthMode.anonKey
51	        ? _anonKey
52	        : (await _tokenStorage.readAccessToken() ?? '');
53	
54	    try {
55	      final response = await _dio.request<Map<String, dynamic>>(
56	        url,
57	        data: body,
58	        queryParameters: queryParameters,
59	        options: Options(
60	          method: method,
61	          headers: {'apikey': _anonKey, 'Authorization': 'Bearer $bearer'},
62	        ),
63	      );
64	      if (!unwrapData) {
65	        return Right(response.data ?? const {});
66	      }
67	      final rawData = response.data?['data'];
68	      if (rawData != null && rawData is! Map<String, dynamic>) {
69	        return Left(
70	          ValidationFailure(
71	            message: 'Malformed response: "data" is not an object',
72	            requestId: '',
73	          ),
74	        );
75	      }
76	      return Right(rawData as Map<String, dynamic>? ?? const {});
77	    } on DioException catch (e) {
78	      return Left(_mapException(e));
79	    }
80	  }
81	
82	  /// Generic SSE transport (research.md R1) — knows nothing about chat
83	  /// specifically; any future SSE-consuming unit reuses it as-is. Never
84	  /// throws past this boundary: a transport failure becomes the stream's one
85	  /// and only `Left(Failure)` item, yielded last, then the stream closes.
86	  Stream<Either<Failure, SseFrame>> sseStream(
87	    String function, {
88	    required String method,
89	    Map<String, dynamic>? body,
90	    List<String>? pathSegments,
91	    AuthMode authMode = AuthMode.userSession,
92	  }) async* {
93	    final baseUrl = dotenv.env['FUNCTIONS_BASE_URL'] ?? '';
94	    final segments = [function, ...?pathSegments];
95	    final url = '$baseUrl/${segments.join('/')}';
96	
97	    final bearer = authMode == AuthMode.anonKey
98	        ? _anonKey
99	        : (await _tokenStorage.readAccessToken() ?? '');
100	
101	    try {
102	      final response = await _dio.request<ResponseBody>(
103	        url,
104	        data: body,
105	        options: Options(
106	          method: method,
107	          responseType: ResponseType.stream,
108	          headers: {'apikey': _anonKey, 'Authorization': 'Bearer $bearer'},
109	        ),
110	      );
111	
112	      final buffer = StringBuffer();
113	      // A bound `Utf8Decoder` (not a per-chunk `utf8.decode`) — a
114	      // multi-byte character (any accented letter, routine in Portuguese
115	      // text) can straddle two network reads; binding it to the byte stream
116	      // carries an incomplete trailing sequence over to the next chunk
117	      // instead of mangling it into replacement characters. `allowMalformed`
118	      // keeps this boundary's "never throws" guarantee for truly invalid
119	      // bytes, same as the per-chunk decode this replaces.
120	      const decoder = Utf8Decoder(allowMalformed: true);
121	      await for (final chunk in decoder.bind(response.data!.stream)) {
122	        buffer.write(chunk);
123	        var text = buffer.toString();
124	        while (text.contains('\n\n')) {
125	          final splitIndex = text.indexOf('\n\n');
126	          final rawFrame = text.substring(0, splitIndex);
127	          text = text.substring(splitIndex + 2);
128	          final frame = _parseFrame(rawFrame);
129	          if (frame != null) yield Right(frame);
130	        }
131	        buffer
132	          ..clear()
133	          ..write(text);
134	      }
135	    } on DioException catch (e) {
136	      yield Left(_mapException(e));
137	    }
138	  }
139	
140	  SseFrame? _parseFrame(String rawFrame) {
141	    String? event;
142	    final dataLines = <String>[];
143	    for (final line in rawFrame.split('\n')) {
144	      if (line.startsWith('event:')) {
145	        event = line.substring(6).trim();
146	      } else if (line.startsWith('data:')) {
147	        dataLines.add(line.substring(5).trim());
148	      }
149	      // Any other SSE field (id:, retry:, comments starting with ':') is
150	      // ignored — this backend's contract never sends them.
151	    }
152	    if (event == null) return null;
153	    return SseFrame(event: event, data: dataLines.join('\n'));
154	  }
