158	      DioExceptionType.connectionTimeout,
159	      DioExceptionType.sendTimeout,
160	      DioExceptionType.receiveTimeout,
161	    };
162	
163	    // `e.message` is Dio's own internal exception text (e.g. "Failed host
164	    // lookup") — never shown to the user; both client-synthesized failures
165	    // below carry a fixed, user-facing message instead, same as every
166	    // backend-mapped `Failure` already does via `ErrorMapper`.
167	    if (timeoutTypes.contains(e.type)) {
168	      return const NetworkTimeoutFailure(
169	        message: 'A conexão demorou demais. Tente novamente.',
170	        requestId: '',
171	      );
172	    }
173	
174	    final responseData = e.response?.data;
175	    if (responseData is Map<String, dynamic>) {
176	      return ErrorMapper.fromResponse(responseData);
177	    }
178	
179	    // No response at all (connection error) — NETWORK_OFFLINE never arrives
180	    // as an HTTP response, so it is synthesized client-side here.
181	    return const NetworkOfflineFailure(
182	      message: 'Sem conexão com a internet.',
183	      requestId: '',
184	    );
185	  }
