  getIt.registerLazySingleton<EntriesLocalCache>(EntriesLocalCache.new);
  getIt.registerLazySingleton<EntriesRepository>(
    () => EntriesRepositoryImpl(
      getIt<EntriesRemoteDataSource>(),
      sessionRepository: getIt<SessionRepository>(),
      localCache: getIt<EntriesLocalCache>(),
    ),
  );
  getIt.registerLazySingleton<CreateEntryUseCase>(
    () => CreateEntryUseCase(getIt<EntriesRepository>()),
  );
  getIt.registerFactory<RecordsBloc>(
    () => RecordsBloc(entriesRepository: getIt<EntriesRepository>()),
  );

  // Chat (P-RF04)
  getIt.registerLazySingleton<ChatLocalCache>(ChatLocalCache.new);
  getIt.registerLazySingleton<ChatRemoteDataSource>(
    () => ChatRemoteDataSource(getIt<ApiClient>()),
  );
  getIt.registerLazySingleton<ChatRepository>(
    () => ChatRepositoryImpl(
      getIt<ChatRemoteDataSource>(),
      sessionRepository: getIt<SessionRepository>(),
      localCache: getIt<ChatLocalCache>(),
